import { Component } from '@angular/core';

@Component({
  selector: 'app-root',
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent {
  title = 'Gerenciador de Produtos';
}
<nav class="navbar">
  <div class="navbar-brand">📦 Gerenciador de Produtos</div>
  <div class="navbar-links">
    <a routerLink="/produtos" routerLinkActive="active">Lista de Produtos</a>
    <a routerLink="/novo-produto" routerLinkActive="active">Cadastrar Produto</a>
  </div>
</nav>

<div class="container">
  <router-outlet></router-outlet>
</div>
